import type { PatenteHistorico } from './Seccion7_6Patentes';

interface FilaTamarindos {
  numero: string;
  fecha: string;
  fechaPublicacion: string;
  descripcion: string;
  tieneEfectosGenerales?: string;
  ultimaActualizacion?: string;
  enlaceModificacion?: string;
}

const crearPermisosTamarindos = (
  filas: FilaTamarindos[],
  efectoGeneralPredeterminado = 'Sí'
): PatenteHistorico[] =>
  filas.map(({
    numero,
    fecha,
    fechaPublicacion,
    descripcion,
    tieneEfectosGenerales = efectoGeneralPredeterminado,
    ultimaActualizacion = 'Sin Modificaciones',
    enlaceModificacion = 'Sin Modificaciones'
  }) => ({
    tipoNorma: 'Decretos Exentos',
    denominacion: 'Patentes y Permisos',
    nombreTitulo: 'Permiso Feria Persa Tamarindos',
    numero,
    fecha,
    fechaPublicacion,
    tieneEfectosGenerales,
    ultimaActualizacion,
    descripcion,
    enlacePublicacion: 'PDF',
    enlaceModificacion,
    urlPublicacion: '',
    urlModificacion: ''
  }));

